with base as (select *, date_add(end_date, 41) as end_date_plus_41d from subscriptions where end_date < '2024-05-27') select case when monthly_fee >= 260 then 'PREMIUM' else 'STANDARD' end as monthly_fee_tier, date_trunc('week', start_date) as week_start, approx_percentile(monthly_fee, 0.95) as monthly_fee_p95, count(*) as num_rows, size(collect_set(plan)) as num_plans, percent_rank() over (partition by case when monthly_fee >= 260 then 'PREMIUM' else 'STANDARD' end order by size(collect_set(plan)) desc) as num_plans_percent_rank from base group by 1, 2 having num_rows > 1;
